      setSelectedLocale(DEFAULT_LOCALE)
      setShouldCascade(cascadeToEvents ?? false)
    } else if (isOpen) {
      setFormState(initialFormState)
      setLocalizationDrafts(emptyLocalizationDrafts())
      setSelectedLocale(DEFAULT_LOCALE)
      setPendingFile(null)
      setShouldCascade(false)
    }
  }, [isOpen, speaker, cascadeToEvents])

