                  </div>

                  <TextField
                    label="Title / Role"
                    value={activeLocaleDraft.title}
                    onChange={updateActiveLocaleTitle}
                    placeholder="e.g., Senior Product Designer at Adobe"
                    styles={style({ width: '[100%]' })}
