                          fontSize: '12px',
                          color: 'var(--emc-cascade-callout-text-muted)',
                          marginTop: '4px',
                        }}
                      >
                        This speaker is linked to events. Check this option to propagate changes to all
                        linked events.
                      </Text>
                    </div>
                  )}
                </div>
              </Form>
            </Content>
