                ) : (
                  <Text>{isEditing ? 'Update Speaker' : 'Add Speaker'}</Text>
                )}
              </Button>
            </ButtonGroup>
          </>
        )}
      </Dialog>
    </DialogTrigger>
  )
}"}]

